import time
import requests
import attr
from taf.sw.dcap.rd.exception import IncorrectLoginCredentials
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AuthorizationFailed(Exception):
    pass


@attr.s(eq=True, frozen=True)
class TokenDetails(object):
    access_token = attr.ib(type=str)
    access_token_expires_in = attr.ib(type=int)
    refresh_token = attr.ib(type=str)
    refresh_token_expires_in = attr.ib(type=int)
    token_creation_time = None

    def __attrs_post_init__(self):
        object.__setattr__(self, "token_creation_time", time.time())

    @property
    def is_access_token_expired(self):
        return self.token_creation_time + self.access_token_expires_in < time.time()

    @property
    def is_refresh_token_expired(self):
        return self.token_creation_time + self.refresh_token_expires_in < time.time()


class Authorization(object):
    TOKEN_URL = 'auth/realms/master/protocol/openid-connect/token'

    @staticmethod
    def _get_refresh_and_access_token_details_with_client_auth(host, port, request_data):
        try:
            token_response = Authorization._get_authorization_response(host=host, port=port,
                                                                       request_data=request_data)
            return TokenDetails(
                access_token=token_response['access_token'],
                access_token_expires_in=int(token_response['expires_in']),
                refresh_token=token_response['refresh_token'],
                refresh_token_expires_in=int(token_response['refresh_expires_in'])
            )

        except Exception:
            raise IncorrectLoginCredentials("username/password might be incorrect or keyclock might be disabled,"
                                            "Please check and pass accordingly")

    @staticmethod
    def get_refresh_and_access_token_details_with_client_auth(host, port, username, password):
        request_data = {
            "username": username,
            "password": password,
            "grant_type": 'password',
            "client_id": "admin-cli"
        }
        return Authorization._get_refresh_and_access_token_details_with_client_auth(host=host,
                                                                                    port=port,
                                                                                    request_data=request_data)

    @staticmethod
    def get_refresh_and_access_token_details_with_refresh_token(refresh_token, host, port):
        request_data = {
            "grant_type": 'refresh_token',
            "client_id": "admin-cli",
            "host": host,
            "port": port,
            "scope": "openid",
            "refresh_token": refresh_token

        }
        return Authorization._get_refresh_and_access_token_details_with_client_auth(host=host,
                                                                                    port=port,
                                                                                    request_data=request_data)

    @staticmethod
    def _auth_response(request_data, client_token_endpoint):
        headers = {"Content-Type": "application/x-www-form-urlencoded"}
        data = request_data
        response = requests.post(
            client_token_endpoint, headers=headers, data=data, verify=False
        )
        response.raise_for_status()
        return response.json()

    @staticmethod
    def _get_authorization_response(host, port, request_data):
        auth_tokens = ["https://{host}:{port}/auth/realms/DCAP/protocol/openid-connect/token",
                       "https://{host}:{port}/dcap/auth/realms/DCAP/protocol/openid-connect/token",
                       "https://{host}:{port}/ptf/auth/realms/AVA/protocol/openid-connect/token",
                       "https://{host}:{port}/utf/auth/realms/AVA/protocol/openid-connect/token"]
        for auth_token in auth_tokens:
            try:
                client_token_endpoint = auth_token.format(host=host, port=port)
                return Authorization._auth_response(
                    request_data=request_data, client_token_endpoint=client_token_endpoint)
            except Exception as e:
                logger.info("failed to get access token from DCAP UI {}".format(e))


class TokenManager(object):

    def __init__(self, host, port, username, password):
        self.host = host
        self.port = port
        self.username = username
        self.password = password
        self.token_object = self.get_access_token()

    @property
    def access_token(self):
        self.assert_token_is_valid()
        return self.token_object.access_token

    def get_access_token(self):
        return Authorization.get_refresh_and_access_token_details_with_client_auth(
            self.host, self.port, self.username, self.password)

    def get_refresh_access_token(self):
        return Authorization.get_refresh_and_access_token_details_with_refresh_token(
            self.token_object.refresh_token, self.host, self.port)

    def assert_token_is_valid(self):
        if self.token_object.is_access_token_expired and not self.token_object.is_refresh_token_expired:
            self.token_object = self.get_refresh_access_token()
        elif self.token_object.is_refresh_token_expired:
            self.token_object = self.get_access_token()


class TokenProvider(object):

    @staticmethod
    def provide_access_token(f):
        def wrapper(dcap_instance, *args, **kwargs):
            if dcap_instance.token:
                dcap_instance.token.assert_token_is_valid()
                TokenProvider._iterate_over_subscribers_and_provide_token(dcap_instance)
            return f(dcap_instance, *args, **kwargs)

        return wrapper

    @staticmethod
    def _iterate_over_subscribers_and_provide_token(self):
        for subscriber in self.token_subscribers:
            subscriber.api_client.api_client.configuration.access_token = self.token.access_token
        return self
